import{_ as r,o as a,c as d,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Классификация и характеристики аномальной энергии","description":"","frontmatter":{},"headers":[],"relativePath":"ru/55-奇异能量分类与特性.md","filePath":"ru/55-奇异能量分类与特性.md","lastUpdated":null}'),l={name:"ru/55-奇异能量分类与特性.md"};function e(o,t,n,h,s,g){return a(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="классификация-и-характеристики-аномальнои-энергии" tabindex="-1">Классификация и характеристики аномальной энергии <a class="header-anchor" href="#классификация-и-характеристики-аномальнои-энергии" aria-label="Permalink to &quot;Классификация и характеристики аномальной энергии&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>55</td></tr><tr><td>Модуль</td><td>Расы и формы жизни</td></tr><tr><td>Ключевые слова</td><td>Аномальная энергия, система классификации, энергетические характеристики, оценка рисков, управление энергией</td></tr></tbody></table><h2 id="i-определение-и-сфера-аномальнои-энергии" tabindex="-1">I. Определение и сфера аномальной энергии <a class="header-anchor" href="#i-определение-и-сфера-аномальнои-энергии" aria-label="Permalink to &quot;I. Определение и сфера аномальной энергии&quot;">​</a></h2><p>В Изначальной Вселенной Ваньлин Хэнмао (Вселенная Хэнъюань) «аномальная энергия» — это формы энергии, которые не принадлежат к обычным типам энергии, охватываемым известными Тремястами Изначальными Системами Культивации, и которые обладают аномальными характеристиками или неизвестным происхождением. Разница между аномальной энергией и аномальной жизнью: аномальная жизнь — это существование с жизненными характеристиками, а аномальная энергия — это форма энергии, не обладающая полными жизненными характеристиками, но могущая обладать аномальной активностью.</p><p>Источники аномальной энергии включают, но не ограничиваются: энергией чужих вселенных, просачивающейся из плоскостных трещин; доисторической энергией, запечатанной в древних руинах; вариантной энергией, произведённой высокоэнергетическими экспериментами; неизвестной энергией, естественно образовавшейся в глубинах вселенной; и особой энергией, сконденсированной из фрагментов законов. Неизвестность и потенциальная опасность аномальной энергии делают её ключевым объектом управления энергией в Симбиотической Цивилизации Якоря.</p><h2 id="ii-система-классификации-аномальнои-энергии" tabindex="-1">II. Система классификации аномальной энергии <a class="header-anchor" href="#ii-система-классификации-аномальнои-энергии" aria-label="Permalink to &quot;II. Система классификации аномальной энергии&quot;">​</a></h2><p>Согласно своим сущностным характеристикам и моделям поведения, аномальная энергия делится на пять основных категорий, каждая из которых далее подразделяется на конкретные типы:</p><h3 id="i-классификация-по-сущности-энергии" tabindex="-1">(I) Классификация по сущности энергии <a class="header-anchor" href="#i-классификация-по-сущности-энергии" aria-label="Permalink to &quot;(I) Классификация по сущности энергии&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Категория</th><th>Название</th><th>Сущностные характеристики</th><th>Представительные типы</th></tr></thead><tbody><tr><td>Первая категория</td><td>Элементарно-вариантный тип</td><td>Произошёл от известных элементарных энергий, сохраняя некоторые элементарные характеристики, но с аномальными проявлениями</td><td>Тёмное Пламя, Мёртвая Вода, Грозовой Ветер, Фиолетовая Молния</td></tr><tr><td>Вторая категория</td><td>Законопроизводный тип</td><td>Непосредственно сконденсирован из фрагментов космических законов, обладает мощью уровня закона</td><td>Временная Энергия, Пространственная Энергия, Энергия Причинности, Энергия Судьбы</td></tr><tr><td>Третья категория</td><td>Тип проекции сознания</td><td>Энергия, образованная проекцией мощного сознания или коллективной мысли, обладающая атрибутами сознания</td><td>Телекинез, Сила Веры, Сила Обета, Сила Проклятия</td></tr><tr><td>Четвёртая категория</td><td>Тип гетерогенного вторжения</td><td>Гетерогенная энергия из других вселенных или плоскостей, не следующая обычным законам этой вселенной</td><td>Энергия Пустоты, Энергия Хаоса, Бездонная Энергия, Энергия Святого Света</td></tr><tr><td>Пятая категория</td><td>Смешанно-вариантный тип</td><td>Новая энергия, произведённая смешанной вариацией двух или более типов энергии, со сложными и изменчивыми характеристиками</td><td>Хаотическая Гром-Огонь, Энергия Пространственно-Временных Трещин, Смешанная Энергия Жизни-Смерти</td></tr></tbody></table><h3 id="ii-классификация-по-модели-поведения-энергии" tabindex="-1">(II) Классификация по модели поведения энергии <a class="header-anchor" href="#ii-классификация-по-модели-поведения-энергии" aria-label="Permalink to &quot;(II) Классификация по модели поведения энергии&quot;">​</a></h3><ul><li><strong>Стабильный тип</strong> : энергия со стабильными свойствами, не изменяющаяся и не распространяющаяся спонтанно, относительно легко контролируемая.</li><li><strong>Активный тип</strong> : энергия с активными свойствами, спонтанно колеблющаяся или распространяющаяся, требующая постоянного мониторинга.</li><li><strong>Эрозивный тип</strong> : обладающий характеристикой разъедания других энергий или материи, непрерывно ассимилирующий окружающую среду.</li><li><strong>Пожирающий тип</strong> : обладающий характеристикой пожирания других энергий для усиления себя, с риском неконтролируемого роста.</li><li><strong>Инфекционный тип</strong> : обладающий инфекционностью, способный заражать другие энергии или формы жизни и преобразовывать их в энергию того же типа.</li><li><strong>Саморазрушительный тип</strong> : нестабильная энергия с риском спонтанного взрыва или аннигиляции.</li><li><strong>Интеллектуальный тип</strong> : энергия, обладающая предварительным сознанием или интеллектом, способная к автономным действиям и решениям.</li></ul><h3 id="iii-классификация-по-уровню-риска-энергии" tabindex="-1">(III) Классификация по уровню риска энергии <a class="header-anchor" href="#iii-классификация-по-уровню-риска-энергии" aria-label="Permalink to &quot;(III) Классификация по уровню риска энергии&quot;">​</a></h3><p>По аналогии с системой оценки рисков аномальной жизни, аномальная энергия также делится на четыре уровня риска:</p><table tabindex="0"><thead><tr><th>Уровень риска</th><th>Название</th><th>Критерии</th><th>Направление обращения</th></tr></thead><tbody><tr><td>Первый уровень</td><td>Низкий риск</td><td>Стабильные свойства, отсутствие эрозивности, пригодна к использованию, контролируемое воздействие на окружающую среду</td><td>Обращение разработки и использования</td></tr><tr><td>Второй уровень</td><td>Средний риск</td><td>Относительно активные свойства, некоторая эрозивность или диффузность, требует контроля</td><td>Обращение запечатывания и наблюдения</td></tr><tr><td>Третий уровень</td><td>Высокий риск</td><td>Сильная эрозивность/пожирание/инфекционность, неконтролируема, серьёзный ущерб окружающей среде</td><td>Обращение очищения и растворения</td></tr><tr><td>Четвёртый уровень</td><td>Чрезвычайно высокий риск</td><td>Обладает разрушительной силой космического уровня, угрозой уровня закона, неконтролируема, угрожает выживанию цивилизации</td><td>Экстренное растворение + доклад</td></tr></tbody></table><h2 id="iii-подробное-объяснение-основных-типов-аномальнои-энергии" tabindex="-1">III. Подробное объяснение основных типов аномальной энергии <a class="header-anchor" href="#iii-подробное-объяснение-основных-типов-аномальнои-энергии" aria-label="Permalink to &quot;III. Подробное объяснение основных типов аномальной энергии&quot;">​</a></h2><h3 id="i-элементарно-вариантныи-тип" tabindex="-1">(I) Элементарно-вариантный тип <a class="header-anchor" href="#i-элементарно-вариантныи-тип" aria-label="Permalink to &quot;(I) Элементарно-вариантный тип&quot;">​</a></h3><ul><li><strong>Тёмное Пламя</strong> : произошло от огненных элементов, тёмно-чёрного цвета, чрезвычайно высокой температуры, но не излучает света, обладает характеристикой пожирания света. Тёмное Пламя может сжигать вещества, которые не могут сжечь обычные пламена, включая энергию и пространство.</li><li><strong>Мёртвая Вода</strong> : произошла от водных элементов, тёмно-зелёного цвета, обладает коррозионными и смертельными атрибутами, способна разъедать жизненную силу форм жизни. Мёртвая Вода обычно используется в некромантических заклинаниях и коррозионной культивации.</li><li><strong>Грозовой Ветер</strong> : произошёл от ветряных элементов, чрезвычайно сильный, с режущими атрибутами, способен разрезать материю и энергию. Грозовой Ветер в основном возникает на больших высотах и вблизи пространственных трещин.</li><li><strong>Фиолетовая Молния</strong> : произошла от громовых элементов, фиолетового цвета, мощь значительно превосходит обычные гром и молнии, обладает характеристикой разрушения законов. Фиолетовая Молния — желанный ресурс культивации для продвинутых культиваторов, но риск её получения чрезвычайно высок.</li></ul><h3 id="ii-законопроизводныи-тип" tabindex="-1">(II) Законопроизводный тип <a class="header-anchor" href="#ii-законопроизводныи-тип" aria-label="Permalink to &quot;(II) Законопроизводный тип&quot;">​</a></h3><ul><li><strong>Временная Энергия</strong> : сконденсирована из фрагментов закона времени, способна ускорять или замедлять локальный поток времени или даже совершать короткие временные прыжки. Временная Энергия чрезвычайно редка и нестабильна; неправильное использование может вызвать временные парадоксы.</li><li><strong>Пространственная Энергия</strong> : сконденсирована из фрагментов закона пространства, способна выполнять операции пространственного складывания, пространственной телепортации и пространственного разрезания. Пространственная Энергия — центральный ресурс системы регулирования пространственных правовых принципов.</li><li><strong>Энергия Причинности</strong> : сконденсирована из фрагментов закона причинности, способна вмешиваться в причинно-следственные цепи и изменять причинно-следственные связи событий. Использование Энергии Причинности строго ограничено для предотвращения причинного беспорядка.</li><li><strong>Энергия Судьбы</strong> : сконденсирована из фрагментов закона судьбы, способна влиять на траектории судьбы форм жизни и изменять удачу и везение. Использование Энергии Судьбы связано с глубокими этическими вопросами и находится под самым строгим контролем.</li></ul><h3 id="iii-тип-проекции-сознания" tabindex="-1">(III) Тип проекции сознания <a class="header-anchor" href="#iii-тип-проекции-сознания" aria-label="Permalink to &quot;(III) Тип проекции сознания&quot;">​</a></h3><ul><li><strong>Телекинез</strong> : энергия, образованная проекцией мощной мысли, способная непосредственно управлять материей и энергией разумом. Телекинез — врождённая способность Niàn Zú (Мысленной Расы) ; другие расы также могут овладеть им путём культивации.</li><li><strong>Сила Веры</strong> : энергия, сконденсированная из веры и поклонения большого числа верующих, обладающая священными атрибутами и целительными способностями. Сила Веры — центральный ресурс божественных систем культивации, но чрезмерная зависимость от Силы Веры может вызвать ассимиляцию сознания верующими.</li><li><strong>Сила Обета</strong> : энергия, сконденсированная из прекрасных желаний всех существ, обладающая созидательными и благословляющими атрибутами. Сила Обета — один из важных источников энергии Симбиотической Цивилизации Якоря; распространение симбиотической концепции может накапливать Силу Обета.</li><li><strong>Сила Проклятия</strong> : энергия, сконденсированная из интенсивного негодования и злобы, обладающая разрушительными и проклинающими атрибутами. Сила Проклятия — опасная негативная энергия; неправильное использование обратится против пользователя и находится под строгим контролем.</li></ul><h3 id="iv-тип-гетерогенного-вторжения" tabindex="-1">(IV) Тип гетерогенного вторжения <a class="header-anchor" href="#iv-тип-гетерогенного-вторжения" aria-label="Permalink to &quot;(IV) Тип гетерогенного вторжения&quot;">​</a></h3><ul><li><strong>Энергия Пустоты</strong> : гетерогенная энергия из пустоты вселенной, обладающая характеристиками небытия и аннигиляции, способная растворять материю и энергию. Энергия Пустоты — опасная энергия космического уровня, должна исследоваться и использоваться в строго изолированных условиях.</li><li><strong>Энергия Хаоса</strong> : первичная энергия из хаотического состояния до рождения вселенной, обладающая бесконечными возможностями и неконтролируемостью. Энергия Хаоса может быть преобразована в любой тип энергии, но процесс преобразования чрезвычайно опасен.</li><li><strong>Бездонная Энергия</strong> : тёмная энергия из бездны вселенной, обладающая коррозионными и развращающими характеристиками, способная разъедать сознание и тело форм жизни. Бездонная Энергия тесно связана с происхождением Тёмных Замещающих Сущностей (см. <em>57-黑暗置换体起源与本质</em>).</li><li><strong>Энергия Святого Света</strong> : священная энергия из высших плоскостей, обладающая очищающими и целительными характеристиками, способная очищать тёмную энергию и исцелять тяжёлые раны. Энергия Святого Света — эффективное оружие против Бездонной Энергии, но чрезмерное использование может вызвать потерю контроля над вознесением жизни.</li></ul><h2 id="iv-анализ-характеристик-аномальнои-энергии" tabindex="-1">IV. Анализ характеристик аномальной энергии <a class="header-anchor" href="#iv-анализ-характеристик-аномальнои-энергии" aria-label="Permalink to &quot;IV. Анализ характеристик аномальной энергии&quot;">​</a></h2><p>По сравнению с обычной энергией, аномальная энергия обладает следующими общими характеристиками:</p><table tabindex="0"><thead><tr><th>Характеристика</th><th>Описание</th></tr></thead><tbody><tr><td>Непредсказуемость</td><td>Модели поведения аномальной энергии часто не следуют обычным энергетическим законам, их трудно точно предсказать</td></tr><tr><td>Высокая активность</td><td>Аномальная энергия обычно обладает высокой активностью, легко вступает в реакции с другими энергиями или материей</td></tr><tr><td>Исключительность</td><td>Часть аномальной энергии обладает исключительностью, отталкивая или растворяя другие типы энергии</td></tr><tr><td>Инфекционность</td><td>Часть аномальной энергии обладает инфекционностью, способна заражать или преобразовывать другие энергии и формы жизни</td></tr><tr><td>Эволюционность</td><td>Аномальная энергия может эволюционировать или варьироваться со временем, производя новые характеристики</td></tr><tr><td>Высокая ценность</td><td>Аномальная энергия часто обладает мощью и применением, несравнимыми с обычной энергией, с чрезвычайно высокой исследовательской и эксплуатационной ценностью</td></tr><tr><td>Высокий риск</td><td>Неизвестность и аномальные характеристики аномальной энергии делают её высокорисковой; неправильный контроль может вызвать серьёзные последствия</td></tr></tbody></table><h2 id="v-обнаружение-и-мониторинг-аномальнои-энергии" tabindex="-1">V. Обнаружение и мониторинг аномальной энергии <a class="header-anchor" href="#v-обнаружение-и-мониторинг-аномальнои-энергии" aria-label="Permalink to &quot;V. Обнаружение и мониторинг аномальной энергии&quot;">​</a></h2><p>Для своевременного обнаружения и контроля аномальной энергии государство создаёт систему обнаружения и мониторинга аномальной энергии:</p><ul><li><strong>Сеть энергетического мониторинга</strong> : создать станции энергетического мониторинга по всей вселенной, отслеживая в реальном времени энергетические колебания в различных регионах и своевременно обнаруживая аномальные энергетические сигналы.</li><li><strong>Мониторинг плоскостных трещин</strong> : проводить целевой мониторинг плоскостных трещин для предотвращения вторжения гетерогенной энергии через трещины.</li><li><strong>Энергетический мониторинг руин</strong> : проводить энергетический мониторинг древних руин и археологических площадок для предотвращения утечки запечатанной аномальной энергии.</li><li><strong>Энергетический мониторинг экспериментов</strong> : проводить энергетический мониторинг высокоэнергетических экспериментов и прорывов культивации для предотвращения потери контроля над случайно произведённой аномальной энергией.</li><li><strong>Система энергетического предупреждения</strong> : создать систему предупреждения аномальной энергии, публикующую разные уровни предупреждающей информации согласно уровню риска энергии.</li></ul><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Аномальная энергия — одно из самых ценных для исследования и самых опасных существований Вселенной Хэнъюань. Создавая систематическую систему классификации, глубоко изучая характеристики различных типов аномальной энергии и создавая сети обнаружения и мониторинга, Симбиотическая Цивилизация Якоря закладывает научную основу для безопасного контроля и рационального использования аномальной энергии. В <em>56-奇异能量三类处置流程</em> будут подробно изложены стандартизированные планы обращения с аномальной энергией на разных уровнях риска.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>56-奇异能量三类处置流程 (Процесс обращения с тремя типами аномальной энергии)</li><li>15-能量循环与转化法则 (Законы циркуляции и преобразования энергии)</li><li>53-奇特生命识别标准 (Стандарты идентификации аномальной жизни)</li><li>57-黑暗置换体起源与本质 (Происхождение и сущность тёмных замещающих сущностей)</li></ul>',33)])])}const c=r(l,[["render",e]]);export{b as __pageData,c as default};
